select jsonb_build_object('captured_at_utc',now(),'schemas',(select jsonb_agg(jsonb_build_object('name',nspname,'acl',nspacl,'owner',pg_get_userbyid(nspowner))) from pg_namespace where nspname='public' or nspname like 'eflow_%' or nspname in ('auth','storage','extensions')),'memberships',(select jsonb_agg(jsonb_build_object('role',r.rolname,'member',m.rolname,'admin',a.admin_option,'inherit',a.inherit_option,'set',a.set_option,'grantor',g.rolname)) from pg_auth_members a join pg_roles r on r.oid=a.roleid join pg_roles m on m.oid=a.member join pg_roles g on g.oid=a.grantor),'default_acl',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'owner',pg_get_userbyid(d.defaclrole),'kind',d.defaclobjtype,'acl',d.defaclacl)) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace),'buckets',(select jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types) order by id) from storage.buckets)) as metadata;
